package gen

import (
	"os"
	"path/filepath"
	"testing"
)

// TestLanguageSwitchPreservesAnotherToolsGeneratedFile: a generator other than
// skgo or polytype signs its output with the same "// Code generated by"
// phrase. Switching a language removes the other mode's skgo module, and it
// finds that module by the generated header — but the generator's name is what
// marks ownership. Another tool's file sits at the path skgo would have
// written, is not skgo's, and must survive.
func TestLanguageSwitchPreservesAnotherToolsGeneratedFile(t *testing.T) {
	t.Parallel()
	const foreign = "// Code generated by acme-tool. DO NOT EDIT.\n\nexport const mine = 1;\n"

	// The app carries the JavaScript-mode modules an earlier choice wrote,
	// except these are another tool's. Regenerating as TypeScript scans exactly
	// these paths for the obsolete mode's artifact.
	root, cfg := foreignFixture(t, jsFixtureRemote, map[string]string{
		"app/web/src/data/data.remote.js": foreign,
		"app/web/src/data/types.js":       foreign,
	})
	cfg.Language = LanguageTypeScript

	if err := Run(cfg); err != nil {
		t.Fatalf("regenerating as TypeScript: %v", err)
	}

	// The switch happened: the TypeScript modules were written.
	for _, want := range []string{"app/web/src/data/data.remote.ts", "app/web/src/data/types.ts"} {
		if _, err := os.Stat(filepath.Join(root, filepath.FromSlash(want))); err != nil {
			t.Fatalf("%s was not written by the switch: %v", want, err)
		}
	}

	// The other tool's files are not skgo's to remove.
	for _, keep := range []string{"app/web/src/data/data.remote.js", "app/web/src/data/types.js"} {
		got, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(keep)))
		if err != nil {
			t.Errorf("switching language removed another tool's generated file %s: %v", keep, err)
			continue
		}
		if string(got) != foreign {
			t.Errorf("%s was rewritten by the switch:\n--- got ---\n%s", keep, got)
		}
	}
}
